package com.smartexam.security;
import io.jsonwebtoken.JwtException; import jakarta.servlet.*; import jakarta.servlet.http.HttpServletRequest; import jakarta.servlet.http.HttpServletResponse; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException; import java.util.List;
@Component public class JwtAuthenticationFilter extends OncePerRequestFilter {
 private final JwtService jwtService; private final ApiAuthenticationEntryPoint entryPoint;
 public JwtAuthenticationFilter(JwtService jwtService,ApiAuthenticationEntryPoint entryPoint){this.jwtService=jwtService;this.entryPoint=entryPoint;}
 @Override protected void doFilterInternal(HttpServletRequest request,HttpServletResponse response,FilterChain chain)throws ServletException,IOException{String h=request.getHeader("Authorization");if(h==null||!h.startsWith("Bearer ")){chain.doFilter(request,response);return;}try{var c=jwtService.parse(h.substring(7));var auth=new UsernamePasswordAuthenticationToken(c.getSubject(),null,List.of(new SimpleGrantedAuthority("ROLE_"+c.get("role",String.class))));SecurityContextHolder.getContext().setAuthentication(auth);chain.doFilter(request,response);}catch(JwtException|IllegalArgumentException e){SecurityContextHolder.clearContext();entryPoint.commence(request,response,null);}}
 }
